// Original Mallside planning tools point only to verified stock at its actual branch.
export const PLAN_BUDGETS=[5000,15000,30000,100000];
export const PLAN_LIMIT=16;
export const isPlanningStore=st=>!!st&&!st.count&&!['food','service','visitor','entertainment','auto','gallery'].includes(st.businessKind);
export function createShoppingPlans({STORES,PRODUCTS,storeById,byId,mallOf,mallForStore,categoryOf,modelKey,price,TAX,owned}){
 const categoryFor=st=>({apparel:'Clothing',shoes:'Footwear',bags:'Bags & accessories',jewelry:'Bags & accessories',eyewear:'Bags & accessories',beauty:'Beauty',tech:'Tech',home:'Hobbies & home',toys:'Hobbies & home',books:'Hobbies & home'})[st?.businessKind]||'all';
 const centers=new Map(),retail=st=>st&&!['food','service','visitor','entertainment','auto','gallery'].includes(st.businessKind);
 function products(store){const mall=mallForStore({mallId:'orange'},store);if(!centers.has(mall.id)){const ids=new Set(mall.sections.flatMap(d=>d.stores));centers.set(mall.id,PRODUCTS.filter(p=>!p.archived&&ids.has(p.store)));}return centers.get(mall.id);}
 function categories(store){return ['all',...new Set(products(store).map(categoryOf))];}
 function validItem(id,store){const p=byId(id);return !!p&&!p.archived&&products(store).includes(p);}
 function normalize(s){const plans=new Map();for(const p of Array.isArray(s.shoppingPlans)?s.shoppingPlans:[]){if(!p||!retail(storeById(p.store))||!Array.isArray(p.items)||!PLAN_BUDGETS.includes(p.budget)||!Number.isSafeInteger(p.day)||p.day<1||p.day>s.day)continue;const items=[...new Set(p.items.filter(id=>typeof id==='string'&&validItem(id,p.store)))].slice(0,3);plans.set(p.store,{store:p.store,category:categories(p.store).includes(p.category)?p.category:'all',budget:p.budget,items,day:p.day});}s.shoppingPlans=[...plans.values()].slice(-PLAN_LIMIT);}
 function draft(s,store){const old=s.shoppingPlans.find(p=>p.store===store);return old?{...old,items:[...old.items]}:{store,category:categories(store).includes(categoryFor(storeById(store)))?categoryFor(storeById(store)):'all',budget:15000,items:[],day:s.day};}
 function candidates(s,store,{category='all',query='',limit=12}={}){const q=String(query).normalize('NFKD').toLowerCase().slice(0,100),list=products(store).filter(p=>(category==='all'||categoryOf(p)===category)&&`${p.brand} ${p.name} ${storeById(p.store).name}`.normalize('NFKD').toLowerCase().includes(q));list.sort((a,b)=>price(s,a)-price(s,b)||a.name.localeCompare(b.name)||a.id.localeCompare(b.id));const seen=new Set();return list.filter(p=>{const key=modelKey(p);if(seen.has(key))return false;seen.add(key);return true;}).slice(0,Math.max(1,Math.min(60,limit)));}
 function summary(s,plan){const lines=plan.items.map(byId).filter(Boolean).map(p=>{const amount=price(s,p),tax=Math.round(amount*TAX);return {p,amount,tax,total:amount+tax,owned:owned(s).some(i=>i.productId===p.id)};});const total=lines.reduce((n,l)=>n+l.total,0);return {lines,total,remaining:plan.budget-total,over:total>plan.budget};}
 function save(s,plan){const st=storeById(plan?.store);if(!retail(st)||!mallOf(s).sections.some(d=>d.stores.includes(st.id)))throw Error('Plan with a shop in your current center.');if(!PLAN_BUDGETS.includes(plan.budget)||!categories(st.id).includes(plan.category)||!Array.isArray(plan.items)||plan.items.length>3||new Set(plan.items).size!==plan.items.length||!plan.items.every(id=>typeof id==='string'&&validItem(id,st.id)))throw Error('Choose up to three verified finds in this center.');const old=s.shoppingPlans.find(p=>p.store===st.id);if(!old&&s.shoppingPlans.length>=PLAN_LIMIT)throw Error('Your notebook holds 16 shortlists. Remove one to make room.');const value={store:st.id,category:plan.category,budget:plan.budget,items:[...plan.items],day:s.day};if(old)s.shoppingPlans[s.shoppingPlans.indexOf(old)]=value;else s.shoppingPlans.push(value);return value;}
 function remove(s,store){s.shoppingPlans=s.shoppingPlans.filter(p=>p.store!==store);}
 return {normalize,draft,candidates,categories,summary,save,remove};
}
